\bigg\}\,,\label{eq:A3SLF1}\\
\widetilde{A}_{4}^{\rm{ SLF}}=&\frac{4}{x\bar{x}}\bigg\{\bar{x}{\bf k}_\bot'^2-\frac{\bf k'_\bot\cdot q_\bot}{{\bf q}_\bot^{2}}\Big[(\bar x-x)({\bf k}_\bot'^2-2\bar{x}{\bf k'_\bot\cdot q_\bot})+\bar x^2{m''_1}^{2}-x^2m_2^2-\bar x^3q^2\Big]\nonumber\\
